# [SAME-SCENARIO] stream_with_language.py\n# Starts IBM Watson Speech-to-Text WebSocket with language model and punctuation\n# settings, and streams microphone audio. Provider credentials are read from\n# environment variables.\n\nimport asyncio\nimport json\nimport os\nimport sys\nfrom ibm_watson import SpeechToTextV1\nfrom ibm_watson.websocket import RecognizeCallback, AudioSource\nimport sounddevice as sd\n\n# Watson offers language models such as \"en-US_BroadbandModel\", \"fr-FR_NarrowbandModel\", etc.\nLANGUAGE_MODEL = os.getenv('IBM_STT_LANGUAGE_MODEL', 'en-US_BroadbandModel')\nENABLE_PUNCTUATION = os.getenv('IBM_STT_ENABLE_PUNCTUATION', 'false')\n\nclass WatsonLangStream:\n    def __init__(self, apikey: str, url: str, language_model: str, enable_punctuation: bool):\n        self.speech_to_text = SpeechToTextV1(\n            auth_type='iam',\n            apikey=apikey,\n            url=url,\n        )\n        self.language_model = language_model\n        self.enable_punctuation = enable_punctuation.lower() == 'true'\n\n    async def stream(self):\n        # Build request headers & parameters for language & punctuation\n        headers = {\n            'X-Watson-Learning-Opt-Out': '0',\n        }\n        params = {\n            'language_customization_id': '',  # leave empty for default model\n            'base_model_name': self.language_model,\n            'customization_id': '',\n            'inactivity_timeout': -1,\n            'keep_alive': 60,\n            'punctuation': 'true' if self.enable_punctuation else 'false',\n            'smart_formatting': 'true',\n        }\n        url = self.speech_to_text._service.url\n\n        # Create WebSocket recogniser\n        recognize_callback = RecognizeCallback(self._on_connect,\n                                               self._on_data,\n                                               self._on_error,\n                                               self._on_close,\n                                               audio_format='audio/l16;rate=16000',\n                                               headers=headers,\n                                               params=params)\n\n        async def microphone_generator():\n            with sd.InputStream(samplerate=16000, channels=1, callback=sd.CallbackFlags):\n                while True:\n                    data = sd.rec(1024, samplerate=16000, channels=1, blocking=True)\n                    yield data.tobytes()\n\n        # Start recognition in background\n        asyncio.create_task(recognize_callback.recognize(url, microphone_generator()))\n        # Keep script running\n        await asyncio.Event().wait()\n\n    def _on_connect(self):\n        print('Connected to Watson STT with language:', self.language_model)\n\n    def _on_data(self, json_data):\n        results = json.loads(json_data)\n        for r in results.get('results', []):\n            alts = r.get('alternatives', [])\n            if alts:\n                txt = alts[0].get('transcript', '')\n                print('Transcript chunk:', txt)\n            else:\n                print('No alternatives in result')\n\n    def _on_error(self, error):\n        print('Error:', error)\n\n    def _on_close(self):\n        print('WebSocket closed')\n\nif __name__ == '__main__':\n    apikey = os.getenv('IBM_STT_APIKEY')\n    url = os.getenv('IBM_STT_URL')\n    if not apikey or not url:\n        print('Set IBM_STT_APIKEY and IBM_STT_URL env vars')\n        sys.exit(1)\n    streamer = WatsonLangStream(apikey, url, LANGUAGE_MODEL, ENABLE_PUNCTUATION)\n    asyncio.run(streamer.stream())\n